INSERT INTO public.data_catalog(id,call_id,name,source_path,metadata) SELECT 'paip-solicitudes-simuladas-2027',id,'PAIP · Solicitudes simuladas 2027 · CSV completo','/cbi/data/paid-aragon/solicitudes_simuladas_2027.csv','{"group": "paip-aragon", "role": "activo", "connection": "csv", "delimiter": ",", "headers": ["id", "ejercicio", "tipo", "nombre", "admisible", "puntuacion", "ayuda_solicitada_eur", "orden_desempate", "convocatoria_origen", "expediente_origen", "estado_origen", "importe_imputado", "fuente_url"], "numeric": ["ejercicio", "puntuacion", "ayuda_solicitada_eur", "orden_desempate", "convocatoria_origen"], "categories": ["admisible", "convocatoria_origen", "estado_origen", "importe_imputado"], "sourceFields": ["fuente_url"], "rowCount": 383, "validation": "generic", "pages": ["paid-aragon-dashboard.html"], "readme": "/cbi/data/paid-aragon/README.md", "description": "Población completa y sintética de 2027. Puntuación, ayuda, admisibilidad y orden de desempate son entradas editables; la página reparte el crédito y recalcula el corte. La solicitud de la reunión sustituye una fila sin guardarse. Si cambia el volumen previsto, se remuestrea esta base hasta ese volumen."}'::jsonb FROM public.calls WHERE code='PAID-ARAGON' ON CONFLICT(id) DO UPDATE SET name=excluded.name,source_path=excluded.source_path,metadata=excluded.metadata;
